Theorem visit_null_root_ok : forall (LBo : list (Z * Z)) (cr : credit) (sp r V S2 kx : Z) (g : eghost),
  g_es g = [] ->
  PML.cps_heap L HI PC_VISIT_NULL r sp EVNN.VSCR (LBo ++ g_lbv g) cr
    (fun R M => PML.entry L R M sp r EVNN.VSCR /\ PML.a0 R V /\ True /\ enc_inv M V S2 g /\ ev_guard (g_es g) EvNull /\ PML.img_ro M /\ PML.lits_ok M /\
                ecredit L cr g kx /\ objs_enc L sp V S2)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (pay : Z),
        PML.a0 R' 1 /\ enc_inv M' V S2 g' /\ g_es g' = estep (g_es g) EvNull /\ pay_ok EvNull pay /\ g_len g' = g_len g + ev_ind (g_es g) EvNull + pay /\
        PML.lits_ok M' /\ LB' = LBo ++ g_lbv g' /\ LBk = LBo /\ W = W_enc V S2 /\ ecredit L cr' g' kx /\ snd cr' = snd cr).
